  var mel = [3, 2, 3, 5, 4, 3, 2, 0, 1, 2, 3, 2, 1, 0, 1, -1, 3, 2, 3, 5, 6, 5, 4, 3, 4, 3, 2, 1, 2, 3, 0, -1, 5, 6, 5];
